import unittest

def count_vowels(s):
    """
    Counts the number of vowels in the given string.

    Parameters:
    s (str): The input string.

    Returns:
    int: The number of vowels in the string.
    """
    return sum(1 for c in s if c.lower() in 'aeiou')

class TestVowelCount(unittest.TestCase):

    def test_normal_string(self):
        self.assertEqual(count_vowels("hello world"), 3)

    def test_empty_string(self):
        self.assertEqual(count_vowels(""), 0)

    def test_no_vowels(self):
        self.assertEqual(count_vowels("bcdfg"), 0)

    def test_all_vowels(self):
        self.assertEqual(count_vowels("aeiou"), 5)

    def test_mixed_case(self):
        self.assertEqual(count_vowels("AEIOU"), 5)

    def test_non_alphabetical(self):
        self.assertEqual(count_vowels("12345!@#$%"), 0)

    def test_spaces(self):
        self.assertEqual(count_vowels("a e i o u"), 5)

    def test_long_string(self):
        self.assertEqual(count_vowels("abcdefghijklmnopqrstuvwxyz"), 5)

if __name__ == '__main__':
    unittest.main()
```

