def find_primes_in_range(start, end):
    """
    Returns a list of all prime numbers within the given range [start, end].

    Parameters:
    start (int): The starting integer of the range.
    end (int): The ending integer of the range.

    Returns:
    list: A list of prime numbers within the specified range.
    """
    def is_prime(n):
        """Check if a number is prime."""
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    if start > end:
        return []

    primes = []
    for num in range(max(start, 2), end + 1):
        if is_prime(num):
            primes.append(num)
    return primes
```

