def find_min_max(numbers):
    """
    Returns a tuple containing the minimum and maximum values in the list.
    If the list is empty, returns None.

    :param numbers: List of integers
    :return: Tuple (min_val, max_val) or None if the list is empty
    """
    if not numbers:
        return None
    min_val = max_val = numbers[0]
    for num in numbers[1:]:
        if num < min_val:
            min_val = num
        elif num > max_val:
            max_val = num
    return (min_val, max_val)
```

