def simple_calculator(operation_string):
    """
    Simulates a simple calculator that performs basic arithmetic operations.

    Parameters:
    operation_string (str): A string containing the operation and two numbers separated by spaces.

    Returns:
    float or str: The result of the arithmetic operation or an error message.
    """
    elements = operation_string.split()
    if len(elements) != 3:
        return "Invalid input format. Use '<operation> <number1> <number2>'"

    op = elements[0]
    try:
        num1 = float(elements[1])
        num2 = float(elements[2])
    except ValueError:
        return "Invalid number format."

    if op == 'add':
        return num1 + num2
    elif op == 'subtract':
        return num1 - num2
    elif op == 'multiply':
        return num1 * num2
    elif op == 'divide':
        if num2 == 0:
            return "Division by zero is not allowed."
        return num1 / num2
    else:
        return "Unsupported operation. Use 'add', 'subtract', 'multiply', or 'divide'."
