import threading

def singleton(cls):
    _instance = None
    _lock = threading.Lock()

    def wrapper(*args, **kwargs):
        nonlocal _instance
        if _instance is None:
            with _lock:
                if _instance is None:
                    _instance = cls(*args, **kwargs)
        return _instance

    return wrapper

@singleton
class Singleton:
    def __init__(self):
        self._store = {}
        self._store_lock = threading.Lock()

    def set(self, key, value):
        """
        Stores the value associated with the given key.

        :param key: The key to store the value under.
        :param value: The value to store.
        """
        with self._store_lock:
            self._store[key] = value

    def get(self, key):
        """
        Returns the value associated with the given key.

        :param key: The key to retrieve the value for.
        :return: The value associated with the key, or None if the key does not exist.
        """
        with self._store_lock:
            return self._store.get(key, None)
```

```python
def power(base, exponent):
    """
    Calculate the power of a number with handling for negative numbers and edge cases.

    Parameters:
    base (int or float): The base number.
    exponent (int or float): The exponent to raise the base to.

    Returns:
    int or float: The result of base raised to the power of exponent.

    Raises:
    ValueError: If base or exponent is not a number.
    ZeroDivisionError: If base is zero and exponent is negative.
    """
    if not isinstance(base, (int, float)) or not isinstance(exponent, (int, float)):
        raise ValueError("Both base and exponent must be numbers.")

    if base == 0:
        if exponent > 0:
            return 0
        elif exponent < 0:
            raise ZeroDivisionError("Cannot raise zero to a negative power.")
        else:
            return 1

    if exponent == 0:
        return 1

    if exponent < 0:
        return 1 / (base ** abs(exponent))

    return base ** exponent
```

