from typing import Union

def calculator(operation: str, num1: float, num2: float) -> Union[float, str]:
    """
    Perform a basic arithmetic operation on two numbers with error handling.

    Parameters:
    operation (str): The arithmetic operation to perform ('+', '-', '*', '/').
    num1 (float): The first operand.
    num2 (float): The second operand.

    Returns:
    Union[float, str]: The result of the operation or an error message.
    """
    try:
        if not isinstance(num1, (int, float)) or not isinstance(num2, (int, float)):
            raise TypeError("Both num1 and num2 should be integers or floats")

        if operation == '+':
            return num1 + num2
        elif operation == '-':
            return num1 - num2
        elif operation == '*':
            return num1 * num2
        elif operation == '/':
            if num2 == 0:
                raise ValueError("Cannot divide by zero")
            return num1 / num2
        else:
            raise ValueError("Invalid operation")
    except Exception as e:
        return str(e)
