class MinStack:
    def __init__(self):
        # Main stack to store all elements
        self.stack = []
        # Min stack to store the minimum elements
        self.min_stack = []

    def push(self, x):
        """Push element x onto stack."""
        self.stack.append(x)
        if not self.min_stack or x <= self.min_stack[-1]:
            self.min_stack.append(x)

    def pop(self):
        """Remove the element on top of the stack."""
        if self.stack:
            value = self.stack.pop()
            if value == self.min_stack[-1]:
                self.min_stack.pop()

    def top(self):
        """Get the top element."""
        if self.stack:
            return self.stack[-1]
        return None

    def get_min(self):
        """Retrieve the minimum element in the stack."""
        if self.min_stack:
            return self.min_stack[-1]
        return None
