def recursive_sum(n):
    """
    Calculate the sum of all even integers from 1 to n using recursion.

    Parameters:
    n (int): A positive integer representing the upper limit.

    Returns:
    int: The sum of all even integers from 1 to n.
    """
    # Base case: if n is less than 2, there are no even numbers to add
    if n < 2:
        return 0

    # Recursive case: if n is even, add it to the sum of even numbers up to n-2
    if n % 2 == 0:
        return n + recursive_sum(n - 2)

    # If n is odd, skip to the previous number (which is even) and continue
    else:
        return recursive_sum(n - 1)
