def fibonacci(n: int) -> int:
    """
    Computes the nth Fibonacci number using memoization to optimize performance.

    Parameters:
    n (int): The position in the Fibonacci sequence (non-negative integer).

    Returns:
    int: The nth Fibonacci number.
    """
    memo = {}

    def fib_helper(x):
        if x in memo:
            return memo[x]
        if x <= 1:
            return x
        else:
            result = fib_helper(x - 1) + fib_helper(x - 2)
            memo[x] = result
            return result

    return fib_helper(n)
