def prime_generator(n):
    """
    Generates all prime numbers up to n using the Sieve of Eratosthenes algorithm.

    Yields each prime number one at a time, optimizing by skipping even numbers
    after processing 2 and only checking odd multiples for marking non-primes.

    :param n: The upper limit for prime number generation (inclusive).
    :yield: Each prime number up to n.
    """
    if n < 2:
        return

    yield 2  # Yield the first prime number

    # Initialize a list to keep track of prime status for odd numbers
    sieve = [True] * ((n - 1) // 2)

    for start in range(3, int(n**0.5) + 1, 2):
        if sieve[(start - 3) // 2]:
            for multiple in range(start * start, n + 1, start * 2):
                sieve[(multiple - 3) // 2] = False

    # Yield the odd primes
    for index in range(0, (n - 1) // 2):
        if sieve[index]:
            yield 2 * index + 3
