class PriorityQueue:
    def __init__(self):
        self.queue = []

    def add(self, task, priority):
        """Adds a task with the given priority to the queue."""
        self.queue.append((priority, len(self.queue), task))

    def remove(self, task):
        """Removes the task from the queue if it exists."""
        self.queue = [(priority, index, t) for priority, index, t in self.queue if t != task]

    def highest_priority(self):
        """Returns the highest priority task without removing it from the queue."""
        if not self.queue:
            return None
        return max(self.queue, key=lambda x: (x[0], -x[1]))[2]

    def tasks(self):
        """Returns a list of all tasks in the queue in order of priority, highest to lowest."""
        sorted_queue = sorted(self.queue, key=lambda x: (x[0], -x[1]), reverse=True)
        return [task for _, _, task in sorted_queue]
