def count_negatives(grid, row=0, col=0):
    """
    Recursively counts the number of negative numbers in a given m x n matrix sorted in non-increasing order
    both row-wise and column-wise.

    :param grid: List[List[int]] - The input matrix.
    :param row: int - The current row index.
    :param col: int - The current column index.
    :return: int - The count of negative numbers in the matrix.
    """
    if row >= len(grid):
        return 0
    if col >= len(grid[0]):
        return count_negatives(grid, row + 1, 0)
    if grid[row][col] < 0:
        return 1 + count_negatives(grid, row, col + 1)
    else:
        return count_negatives(grid, row, col + 1)
