    Generate a list of prime numbers up to and including n.

    Parameters:
    n (int): The upper limit for generating prime numbers.

    Returns:
    list: A list of prime numbers up to and including n.
    """
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
