def round_to_nearest_quarter(lst):
    """
    Rounds each number in the input list to the nearest quarter integer.
    If the number is exactly halfway between two quarter integers, it rounds away from zero.

    :param lst: List of floating-point numbers.
    :return: List of nearest quarter integers.
    """
    def round_away_from_zero(val):
        if val > 0:
            return int(val + 0.5)
        else:
            return int(val - 0.5)

    rounded_list = []
    for num in lst:
        quarter_val = num * 4  # scale up to make it easier to round to nearest integer
        rounded_quarter_val = round_away_from_zero(quarter_val)
        rounded_num = rounded_quarter_val / 4  # scale back down
        rounded_list.append(rounded_num)

    return rounded_list
