def parse_robot_positions(positions):
    """
    Parses a list of robot positions into a list of tuples containing floor numbers and directions.

    :param positions: List of strings representing robot positions.
    :return: List of tuples with floor numbers and directions.
    """
    def helper(index):
        if index == len(positions):
            return []

        position = positions[index]
        direction = None
        if position[-1] in ['U', 'D']:
            direction = position[-1]
            floor = int(position[:-1])
