def parse_boolean(s: str, strict: bool = False) -> bool:
    """
    Parses a string into a boolean value based on custom rules.

    Parameters:
    s (str): The string to parse.
    strict (bool): If True, only "true" and "false" are accepted.

    Returns:
    bool: The parsed boolean value.

    Raises:
    ValueError: If the string cannot be parsed as a boolean.
    """
    s = s.strip().lower()
    true_set = {"true", "yes", "1", "t", "y"}
    false_set = {"false", "no", "0", "f", "n"}

    if not s:
        raise ValueError("String is empty or only contains spaces.")

    if strict:
        if s == "true":
            return True
        elif s == "false":
            return False
        else:
            raise ValueError(f"Invalid boolean string: {s} in strict mode.")
    else:
        words = s.split()
        if len(words) > 1:
            raise ValueError(f"String contains multiple words: {s}. Only one boolean value expected.")
        for word in words:
            if word in true_set:
                return True
            elif word in false_set:
                return False
        raise ValueError(f"Unrecognized boolean string: {s}.")
