from typing import List

def find_primes(n: int) -> List[int]:
    """
    Returns a list of all prime numbers up to and including n using an optimized Sieve of Eratosthenes algorithm.

    :param n: The upper limit integer up to which primes are to be found.
    :return: A list of prime numbers up to and including n.
    """
    if n < 2:
        return []
    elif n == 2:
        return [2]

    prime_status = [True] * ((n-3)//2 + 1)

    for i in range(len(prime_status)):
        current_number = 2 * i + 3
        if current_number * current_number > n:
            break
        if prime_status[i]:
            for multiple in range(current_number*current_number, n+1, 2*current_number):
                if multiple % 2 != 0:
                    prime_status[(multiple-3)//2] = False

    primes = [2]
    for i in range(len(prime_status)):
        if prime_status[i]:
            primes.append(2 * i + 3)

    return primes
