def is_palindrome(s):
    """
    Determines if the given string s is a palindrome, ignoring spaces, punctuation, and capitalization.

    :param s: The input string to check.
    :return: True if s is a palindrome, False otherwise.
    """
    def clean_and_check(s, left, right):
        if left >= right:
            return True
        if not s[left].isalnum():
            return clean_and_check(s, left + 1, right)
        if not s[right].isalnum():
            return clean_and_check(s, left, right - 1)
        if s[left].lower() != s[right].lower():
            return False
        return clean_and_check(s, left + 1, right - 1)

    return clean_and_check(s, 0, len(s) - 1)

