def get_config_value(config, path, default=None):
    """
    Retrieve the value from a nested JSON configuration given a path.

    :param config: dict, The configuration dictionary.
    :param path: list of str and int, A list representing the path to the desired value.
    :param default: any, The default value to return if the path is invalid.
    :return: any, The value at the specified path or the default value if the path does not exist.
    """
    try:
        for key in path:
            if isinstance(config, dict) and key in config:
                config = config[key]
            elif isinstance(config, list) and isinstance(key, int) and 0 <= key < len(config):
                config = config[key]
            else:
                return default
        return config
    except (TypeError, IndexError):
