class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class Stack:
    def __init__(self):
        self.top = None

    def is_empty(self):
        """Returns True if the stack is empty, otherwise False."""
        return self.top is None

    def push(self, data):
        """Adds an element to the top of the stack."""
        new_node = Node(data)
        new_node.next = self.top
        self.top = new_node

    def pop(self):
        """Removes the top element from the stack and returns it. Raises an IndexError if the stack is empty."""
        if self.is_empty():
            raise IndexError("Stack is empty")
        popped_node = self.top
        self.top = self.top.next
        return popped_node.data

    def peek(self):
        """Returns the top element of the stack without removing it. Raises an IndexError if the stack is empty."""
        if self.is_empty():
            raise IndexError("Stack is empty")
        return self.top.data

    def size(self):
        """Returns the number of elements in the stack."""
        current = self.top
        count = 0
        while current is not None:
            count += 1
            current = current.next
        return count
