import logging
from functools import wraps

def temporary_log_level_change(log_level_changes):
    """
    Decorator to temporarily change the log levels of specified loggers.

    Args:
        log_level_changes (dict): A dictionary mapping logger names to their temporary log levels.

    Returns:
        function: A decorator that can be applied to any function to change log levels temporarily.
    """
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Save original levels
            original_levels = {name: logging.getLogger(name).getEffectiveLevel() for name in log_level_changes}

            # Set new log levels
            for name, level in log_level_changes.items():
                logging.getLogger(name).setLevel(level)

            try:
                # Execute the function
                return func(*args, **kwargs)
            finally:
                # Restore original log levels
                for name, level in original_levels.items():
                    logging.getLogger(name).setLevel(level)

        return wrapper
    return decorator
