def find_max_min_pair(numbers):
    """
    Returns a tuple containing the maximum and minimum values from the list.
    If the list is empty, returns None. If the list has a single element, returns a tuple with that element repeated.

    :param numbers: List of integers
    :return: Tuple (max_val, min_val) or None
    """
    if not numbers:
        return None
    elif len(numbers) == 1:
        return (numbers[0], numbers[0])

    max_val = min_val = numbers[0]
    for num in numbers[1:]:
        if num > max_val:
            max_val = num
        elif num < min_val:
            min_val = num

    return (max_val, min_val)

