def round_and_truncate(x, digits):
    """
    Rounds the floating-point number x to 'digits' decimal places if digits is non-negative,
    or truncates x to the nearest multiple of 10^(-digits) if digits is negative.

    Parameters:
    x (float): The number to be rounded or truncated.
    digits (int): The number of decimal places to round to, or the power of ten to truncate to.

    Returns:
    float: The rounded or truncated number.
    """
    if digits < 0:
        factor = 10 ** -digits
        if x >= 0:
            return int(x // factor) * factor
        else:
            return int(-(-x // factor)) * factor
    else:
        return round(x, digits)
