def recursive_product(a, b):
    """
    Recursively calculates the product of two integers without using the multiplication operator.

    :param a: First integer
    :param b: Second integer
    :return: Product of a and b
    """
    if b == 0:
        return 0
    if b == 1:
        return a
    if b % 2 == 0:
        half_product = recursive_product(a, b // 2)
        return add(half_product, half_product)
    else:
        return add(a, recursive_product(a, b - 1))

def product_of_n(n):
    """
    Computes the product of all integers from 1 to n using recursion.

    :param n: Upper limit of the range (inclusive)
    :return: Product of all integers from 1 to n
    """
    if n == 0:
        return 1
    return recursive_product(n, product_of_n(n - 1))
